import{_ as e,a0 as l,w as o,s as d,I as a,x as n,a1 as p,A as i,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"在 Ubuntu 16.04 上配置 msmtp | LCTT x X-CMD","titleTemplate":false,"description":"在 Ubuntu 16.04 上配置 msmtp | LCTT (201804) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Ubuntu 16.04 上配置 msmtp | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Ubuntu 16.04 上配置 msmtp | LCTT (201804) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201804/20180118 Configuring MSMTP On Ubuntu 16.04 (Again)","title":"在 Ubuntu 16.04 上配置 msmtp","tag":"201804","desc":""},"relativePath":"201804/20180118 Configuring MSMTP On Ubuntu 16.04 (Again).md","filePath":"[post].md"}'),u={name:"201804/20180118 Configuring MSMTP On Ubuntu 16.04 (Again).md"};function g(m,s,c,h,b,k){const t=l("Link");return o(),d("div",null,[s[16]||(s[16]=a("h1",{id:"在-ubuntu-16-04-上配置-msmtp",tabindex:"-1"},[n("在 Ubuntu 16.04 上配置 msmtp "),a("a",{class:"header-anchor",href:"#在-ubuntu-16-04-上配置-msmtp","aria-label":"Permalink to “在 Ubuntu 16.04 上配置 msmtp”"},"​")],-1)),s[17]||(s[17]=a("p",null,"这篇文章是在我之前的博客中发表过的在 Ubuntu 16.04 上配置 MSMTP 的一个副本。我再次发表是为了后续，我并不知道它是否能在更高版本上工作。由于我没有再托管自己的 Ubuntu/MSMTP 服务器了，所以我现在看不到有需要更新的地方，但是如果我需要重新设置，我会创建一个更新的帖子！无论如何，这是我现有的。",-1)),s[18]||(s[18]=a("p",null,"我之前写了一篇在 Ubuntu 12.04 上配置 msmtp 的文章，但是正如我在之前的文章中暗示的那样，当我升级到 Ubuntu 16.04 后出现了一些问题。接下来的内容基本上是一样的，但 16.04 有一些小的更新。和以前一样，这里假定你使用 Apache 作为 Web 服务器，但是我相信如果你选择其他的 Web 服务器，也应该相差不多。",-1)),a("p",null,[s[1]||(s[1]=n("我使用 ",-1)),p(t,{href:"http://msmtp.sourceforge.net/"},{default:i(()=>[...s[0]||(s[0]=[n("msmtp",-1)])]),_:1}),s[2]||(s[2]=n(" 发送来自这个博客的邮件俩通知我评论和更新等。这里我会记录如何配置它通过 Google Apps 帐户发送电子邮件，虽然这应该与标准的 Google 帐户一样。",-1))]),s[19]||(s[19]=r(`<p>首先，我们需要安装 3 个软件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install msmtp msmtp-mta ca-certificates</span></span></code></pre></div><p>安装完成后，就需要一个默认配置。默认情况下，msmtp 会在 <code>/etc/msmtprc</code> 中查找，所以我使用 <code>vim</code> 创建了这个文件，尽管任何文本编辑器都可以做到这一点。这个文件看起来像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Set defaults.</span></span>
<span class="line"><span>defaults</span></span>
<span class="line"><span># Enable or disable TLS/SSL encryption.</span></span>
<span class="line"><span>tls on</span></span>
<span class="line"><span>tls_starttls on</span></span>
<span class="line"><span>tls_trust_file /etc/ssl/certs/ca-certificates.crt</span></span>
<span class="line"><span># Setup WP account&#39;s settings.</span></span>
<span class="line"><span>account GMAIL</span></span>
<span class="line"><span>host smtp.gmail.com</span></span>
<span class="line"><span>port 587</span></span>
<span class="line"><span>auth login</span></span>
<span class="line"><span>user YOUR USERNAME</span></span>
<span class="line"><span>password YOUR PASSWORD</span></span>
<span class="line"><span>from FROM@ADDRESS</span></span>
<span class="line"><span>logfile /var/log/msmtp/msmtp.log</span></span>
<span class="line"><span></span></span>
<span class="line"><span>account default :</span></span></code></pre></div><p>任何大写选项都是需要替换为你特定的配置。日志文件是一个例外，当然你也可以将活动/警告/错误放在任何你想要的地方。</p><p>文件保存后，我们将更新上述配置文件的权限 ，如果该文件的权限过于开放，msmtp 将不会运行，并且创建日志文件的目录。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo mkdir /var/log/msmtp</span></span>
<span class="line"><span>sudo chown -R www-data:adm /var/log/msmtp</span></span>
<span class="line"><span>sudo chmod 0600 /etc/msmtprc</span></span></code></pre></div><p>接下来，我选择为 msmtp 日志配置 logrotate，以确保日志文件不会太大并让日志目录更加整洁。为此，我们创建 <code>/etc/logrotate.d/msmtp</code> 并使用按以下内容配置。请注意，这是可选的，你可以选择不这样做，或者你可以选择以不同方式配置日志。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/var/log/msmtp/*.log {</span></span>
<span class="line"><span>	rotate 12</span></span>
<span class="line"><span>	monthly</span></span>
<span class="line"><span>	compress</span></span>
<span class="line"><span>	missingok</span></span>
<span class="line"><span>	notifempty</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>现在配置了日志，我们需要通过编辑 <code>/etc/php/7.0/apache2/php.ini</code> 告诉 PHP 使用 msmtp，并将 sendmail 路径从</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sendmail_path =</span></span></code></pre></div><p>变成</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sendmail_path = &quot;/usr/bin/msmtp -C /etc/msmtprc -a -t&quot;</span></span></code></pre></div><p>这里我遇到了一个问题，即使我指定了帐户名称，但是当我测试它时，它并没有正确发送电子邮件。这就是为什么 <code>account default : </code> 这行被放在 msmtp 配置文件的末尾。要测试配置，请确保 PHP 文件已保存并运行 <code>sudo service apache2 restart</code>，然后运行 <code>php -a</code> 并执行以下命令</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mail (&#39;personal@email.com&#39;, &#39;Test Subject&#39;, &#39;Test body text&#39;);</span></span>
<span class="line"><span>exit();</span></span></code></pre></div><p>此时发生的任何错误都将显示在输出中，因此错误诊断会相对容易。如果一切顺利，你现在应该可以使用 PHP sendmail（至少 WordPress 可以）中用 Gmail（或 Google Apps）从 Ubuntu 服务器发送电子邮件。</p><p>我没有说这是最安全的配置，所以当你看到并且意识要这个非常不安全，或者有其他严重的错误，请让我知道，我会相应地更新。</p><hr>`,18)),a("p",null,[s[4]||(s[4]=n("via: ",-1)),p(t,{href:"https://codingproductivity.wordpress.com/2018/01/18/configuring-msmtp-on-ubuntu-16-04-again/"},{default:i(()=>[...s[3]||(s[3]=[n("https://codingproductivity.wordpress.com/2018/01/18/configuring-msmtp-on-ubuntu-16-04-again/",-1)])]),_:1})]),a("p",null,[s[8]||(s[8]=n("作者：",-1)),p(t,{href:"https://codingproductivity.wordpress.com/author/joeb454/"},{default:i(()=>[...s[5]||(s[5]=[n("JOE",-1)])]),_:1}),s[9]||(s[9]=n(" 译者：",-1)),p(t,{href:"https://github.com/geekpi"},{default:i(()=>[...s[6]||(s[6]=[n("geekpi",-1)])]),_:1}),s[10]||(s[10]=n(" 校对：",-1)),p(t,{href:"https://github.com/wxy"},{default:i(()=>[...s[7]||(s[7]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[13]||(s[13]=n("本文由 ",-1)),p(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[11]||(s[11]=[n("LCTT",-1)])]),_:1}),s[14]||(s[14]=n(" 原创编译，",-1)),p(t,{href:"https://linux.cn/"},{default:i(()=>[...s[12]||(s[12]=[n("Linux中国",-1)])]),_:1}),s[15]||(s[15]=n(" 荣誉推出",-1))])])}const y=e(u,[["render",g]]);export{T as __pageData,y as default};
